export class StressTesting {
  constructor() {
    this.scenarios = [];
  }

  addScenario(name, scenarioFunction) {
    this.scenarios.push({ name, scenarioFunction });
  }

  runTests() {
    this.scenarios.forEach(({ name, scenarioFunction }) => {
      try {
        console.log(`Running scenario: ${name}`);
        scenarioFunction();
      } catch (error) {
        console.error(`Scenario ${name} failed with error:`, error);
      }
    });
  }
}